require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');
$credentials=$_SESSION['generated_participant_credentials']??[];header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');admin_page_start('Participant Credentials','participants');?>
<div class="hero"><div><h2>Login credentials</h2><p>Provide these credentials to participants. Passwords cannot be recovered after leaving this page.</p></div><a class="btn secondary" href="index.php"><i class="fa-solid fa-check"></i> Done</a></div>
<?php if($credentials):?><div class="alert"><i class="fa-solid fa-shield-halved"></i> <strong><?=count($credentials)?> accounts generated.</strong> Print or download this list now; plain-text passwords are shown only in this temporary session view.</div><div class="card"><div class="table-wrap"><table id="credentialTable"><thead><tr><th>#</th><th>Campaign</th><th>Participant ID</th><th>Temporary password</th><th>Full name</th><th>Group</th></tr></thead><tbody><?php foreach($credentials as $i=>$c):?><tr><td><?=$i+1?></td><td><?=h($c['campaign'])?></td><td><span class="badge"><?=h($c['code'])?></span></td><td><strong><?=h($c['password'])?></strong></td><td><?=h($c['name'])?></td><td><?=h($c['group']?:'—')?></td></tr><?php endforeach;?></tbody></table></div><div class="actions" style="margin-top:18px"><button class="btn" onclick="downloadCredentials()"><i class="fa-solid fa-file-csv"></i> Download CSV</button><button class="btn secondary" onclick="window.print()"><i class="fa-solid fa-print"></i> Print</button></div></div><?php else:?><div class="card empty"><i class="fa-solid fa-key" style="font-size:42px"></i><h3>No generated credentials</h3><p>Generate participant accounts first.</p><a class="btn" href="generate.php">Generate accounts</a></div><?php endif;?>
<script>function downloadCredentials(){const rows=[...document.querySelectorAll('#credentialTable tr')].map(row=>[...row.cells].map(cell=>'"'+cell.innerText.replace(/"/g,'""')+'"').join(','));const blob=new Blob([rows.join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='participant_credentials_'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(a.href)}</script><style>@media print{.sidebar,.topbar,.hero .btn,.actions{display:none!important}.main{margin:0}.admin-bg{display:none}.content{padding:0}.card{border:0;box-shadow:none}}</style>
